from html import escape

DATA={
 'private':('24 000 ₸','2 часа','1–2 человека','С 14 лет','Ежедневно · 09:00 / 12:00 / 15:00'),
 'group':('12 000 ₸','2 часа','До 6 человек','С 14 лет','Сб и Вс · 10:00 / 13:00'),
 'courses':('68 000 ₸','4 × 2 часа','До 6 человек','С 14 лет','Суббота · 10:00 · четыре недели'),
 'kids':('16 000 ₸','90 минут','До 4 детей','6–12 лет','Сб и Вс · 10:00 / 12:00')}

def enrich(home,about,contact,program,cards,programs,photos,button):
 demo='<aside class="demo-notice">Демонстрационная школа · программы, цены, команда и локация вымышлены · запись не производится</aside>'
 newcards='<div class="program-grid photo-programs">'
 for i,p in enumerate(programs):
  price,duration,size,age,schedule=DATA[p[0]]
  newcards+=f'<a class="program" href="{p[0]}.html"><div class="program-photo"><img src="{photos["hero" if i%2==0 else "snow"]}" loading="lazy" alt="Катание на горных лыжах — иллюстративное фото"></div><div class="program-body"><span class="tag">{p[4]} · {age}</span><h3>{p[1]}</h3><p>{p[2]}</p><div class="program-facts"><span>{duration}</span><span>{size}</span></div><div class="program-price"><strong>{price}</strong><span>за участника</span></div><span class="card-link">Программа и условия</span></div></a>'
 newcards+='</div><p class="demo-caption">Пример тарифов для дизайн-концепции. Прокат и ски-пасс оплачиваются отдельно.</p>'
 home=home.replace(cards(),newcards)
 finder='''<section class="section level-finder" id="level"><div class="section-heading"><p class="eyebrow">ВАША ТОЧКА СТАРТА</p><h2>Найдём свой<br>ритм на склоне.</h2><p>Выберите направление и опыт. Подбор предварительный: окончательный уровень оценивает инструктор.</p></div><div class="finder-layout"><div class="finder-controls"><fieldset><legend>На чём будем кататься?</legend><div class="segmented"><label><input type="radio" name="finder-sport" value="ski" checked><span>Горные лыжи</span></label><label><input type="radio" name="finder-sport" value="board"><span>Сноуборд</span></label></div></fieldset><fieldset><legend>Как чувствуете себя на снегу?</legend><div class="level-options"><label><input type="radio" name="finder-level" value="start" checked><span><strong>Пока только мечтаю</strong><small>Никогда не катался или начинаю заново</small></span></label><label><input type="radio" name="finder-level" value="progress"><span><strong>Первые спуски уже были</strong><small>Торможу, пробую поворачивать, хочу уверенности</small></span></label><label><input type="radio" name="finder-level" value="advanced"><span><strong>Хочу точнее и свободнее</strong><small>Катаюсь уверенно, работаю над техникой</small></span></label></div></fieldset></div><div class="finder-result" aria-live="polite"><span class="eyebrow">РЕКОМЕНДАЦИЯ</span><h3 id="finder-title">Спокойный первый шаг.</h3><p id="finder-description">Начните с индивидуального знакомства с лыжами: экипировка, равновесие и управляемая остановка.</p><ul id="finder-skills"><li>Привыкнуть к снаряжению</li><li>Научиться контролировать скорость</li><li>Попробовать первые повороты</li></ul><a class="button dark" id="finder-link" href="private.html">Посмотреть индивидуальные уроки</a></div></div></section>'''
 lesson=f'''<section class="section first-lesson"><div class="lesson-picture"><img src="{photos['snow']}" alt="Лыжник на снежном склоне — иллюстративное фото" loading="lazy"><span>ПЕРВОЕ ЗАНЯТИЕ · ПРИМЕР ПРОГРАММЫ</span></div><div class="lesson-copy"><p class="eyebrow">БЕЗ НЕИЗВЕСТНОСТИ</p><h2>Знакомство.<br>Движение.<br>Первый поворот.</h2><div class="lesson-step"><span>До старта</span><h3>Встречаемся у школы</h3><p>Знакомимся, обсуждаем опыт и проверяем посадку ботинок, крепления и шлем.</p></div><div class="lesson-step"><span>На учебном склоне</span><h3>Чувствуем опору</h3><p>Учимся двигаться в снаряжении, держать равновесие и останавливаться.</p></div><div class="lesson-step"><span>В конце занятия</span><h3>Собираем всё вместе</h3><p>Практикуем движения и обсуждаем, что получилось и чему посвятить следующий урок.</p></div></div></section>'''
 team='''<section class="section team-section" id="team"><div class="section-heading"><p class="eyebrow">ЛЮДИ НА СКЛОНЕ</p><h2>Рядом — тот,<br>кто умеет объяснить.</h2><p>Демонстрационные профили инструкторов. Имена, опыт и специализации вымышлены.</p></div><div class="team-grid">'''
 for initials,name,role,experience,quote in [
 ('АМ','Алексей Морозов','Горные лыжи · взрослые','8 сезонов · русский / английский','«Сначала помогу почувствовать контроль. Скорость придёт позже». '),
 ('ДС','Дарья Соколова','Детские занятия','6 сезонов · русский','«Через игру ребёнок быстрее понимает движение и меньше боится ошибиться». '),
 ('МК','Максим Ким','Сноуборд · техника','7 сезонов · русский / английский','«Разберём один сложный поворот на несколько простых действий». ')]:
  team+=f'<article class="coach"><div class="coach-art" aria-hidden="true"><span>{initials}</span><svg viewBox="0 0 300 170"><path d="M-20 170 90 32l54 72 36-47 140 113M63 67l27 20 16-17"/></svg></div><p class="tag">{role}</p><h3>{name}</h3><p class="coach-experience">{experience}</p><blockquote>{quote}</blockquote><small>Вымышленный профиль</small></article>'
 team+='</div></section>'
 schedule='<section class="section schedule-section"><div class="section-heading"><p class="eyebrow">ПЛАН НА ВЫХОДНЫЕ</p><h2>Освободите утро.<br>Остальное — снег.</h2><p>Пример недельного расписания. Это демонстрация форматов, а не доступные для бронирования занятия.</p></div><div class="schedule-list">'
 for p in programs:
  price,duration,size,age,time=DATA[p[0]]
  schedule+=f'<a class="schedule-row" href="{p[0]}.html"><span>{time}</span><strong>{p[1]}</strong><span>{duration} · {size}</span><b>{price}</b></a>'
 schedule+='</div></section>'
 location=f'''<section class="location-section"><div class="location-graphic" role="img" aria-label="Условная схема: учебный склон, школа и прокат"><svg viewBox="0 0 600 450"><path class="contour" d="M-80 410Q130 10 390 65T720 110M-80 450Q130 50 390 105T720 150M-80 490Q130 90 390 145T720 190M-80 530Q130 130 390 185T720 230M-80 570Q130 170 390 225T720 270M-80 610Q130 210 390 265T720 310"/><path class="route" d="M420 70Q320 180 360 245T215 350"/><circle cx="215" cy="350" r="10"/><circle cx="420" cy="70" r="6"/><text x="95" y="390">ШКОЛА И ПРОКАТ</text><text x="350" y="45">УЧЕБНЫЙ СКЛОН</text><text x="25" y="30" class="map-label">УСЛОВНАЯ СХЕМА</text></svg></div><div class="location-copy"><p class="eyebrow">ВСТРЕЧАЕМСЯ В ГОРАХ</p><h2>Одна точка.<br>Простой старт.</h2><p>Учебная база «Северный склон» — вымышленная локация для концепции. Школа, прокат и место встречи собраны у подножия учебной трассы.</p><dl><div><dt>Место встречи</dt><dd>Павильон школы, рядом с прокатом</dd></div><div><dt>Когда приходить</dt><dd>За 30 минут до начала занятия</dd></div><div><dt>Время работы</dt><dd>Ежедневно, 08:30–17:00 · пример</dd></div></dl>{button('Подготовиться к занятию','contact.html','button dark')}</div></section>'''
 faq='''<section class="section faq"><p class="eyebrow">ЧТО ВАЖНО ПЕРЕД СТАРТОМ</p><h2>Меньше вопросов.<br>Больше предвкушения.</h2><details><summary>Что входит в примерную стоимость?</summary><p>Работа инструктора по выбранной программе. Прокат оборудования, ски-пасс и питание в демонстрационные тарифы не включены.</p></details><details><summary>Можно ли учиться вместе с другом?</summary><p>В нашей демонстрационной программе индивидуальный урок рассчитан на 1–2 человек схожего уровня. Для большей компании предусмотрен групповой формат.</p></details><details><summary>Что взять на первое занятие?</summary><p>Шлем, маску, перчатки, термобельё и непромокаемую верхнюю одежду. Подготовьте подходящие ботинки и лыжи или сноуборд; приходите заранее для проверки экипировки.</p></details><details><summary>Можно забронировать занятие на сайте?</summary><p>Пока нет. Это демонстрационная версия: подбор помогает познакомиться с форматами, но не создаёт заявку и не принимает оплату.</p></details></section>'''
 # Replace the generic preparation block with a complete learning story.
 start=home.index('<section class="section preparation">')
 home=demo+home[:start]+finder+lesson+team+schedule+location+faq+home[home.rfind('<section class="cta">'):]
 about=demo+about.replace('<section class="cta">',team+location+'<section class="cta">',1)
 contact=demo+contact+location
 contact=contact.replace('Контакты школы появятся после согласования с заказчиком.','Демонстрационные тарифы: от 12 000 ₸ за групповое занятие. Выберите формат — покажем пример условий.')
 oldprogram=program
 def expanded(p):
  price,duration,size,age,time=DATA[p[0]]
  facts=f'<section class="lesson-summary"><div><span>Стоимость · демо</span><strong>{price}</strong><small>за участника</small></div><div><span>Продолжительность</span><strong>{duration}</strong></div><div><span>Участники</span><strong>{size}</strong></div><div><span>Возраст</span><strong>{age}</strong></div></section><section class="section booking-info"><div><p class="eyebrow">КОГДА ВСТРЕЧАЕМСЯ</p><h3>{time}</h3><p>Пример расписания. Реальные занятия и бронирование пока недоступны.</p></div><div><h3>Что входит</h3><p>Работа инструктора, упражнения по уровню и обратная связь. Прокат, ски-пасс и питание оплачиваются отдельно.</p></div></section>'
  body=oldprogram(p).replace('<section class="section detail-layout">',facts+'<section class="section detail-layout">',1)
  if p[0]=='kids':
   parent_info='<section class="section"><p class="eyebrow">РОДИТЕЛЯМ · ПРИМЕР УСЛОВИЙ</p><h2>Маленькая группа.<br>Много внимания.</h2><div class="three"><article><h3>Знакомство через игру</h3><p>Первые задания — баланс, шаги и скольжение. В демонстрационном формате урок длится 90 минут, с паузами по самочувствию ребёнка.</p></article><article><h3>Дети похожего уровня</h3><p>Группа до четырёх детей 6–12 лет. Возраст и навыки учитываются вместе: начинающие занимаются отдельно от уверенно катающихся.</p></article><article><h3>Связь с родителями</h3><p>Встреча и завершение — у павильона школы. В конце инструктор рассказывает, что ребёнок попробовал и какие навыки стоит закрепить.</p></article></div></section>'
   body=body.replace('<section class="section faq">',parent_info+'<section class="section faq">',1)
  if p[0]=='courses':
   course_info='<section class="section"><p class="eyebrow">ЧЕТЫРЕ ВСТРЕЧИ · ПРИМЕР ПЛАНА</p><h2>Одна цель.<br>Последовательная работа.</h2><div class="three"><article><h3>Находим точку старта</h3><p>Первое занятие: оцениваем движения, повторяем контроль скорости и выбираем техническую задачу по уровню.</p></article><article><h3>Закрепляем движения</h3><p>Вторая и третья встречи: упражнения на баланс, траекторию и ритм, практика с обратной связью.</p></article><article><h3>Собираем результат</h3><p>Четвёртое занятие: связываем навыки в спусках и составляем рекомендации для дальнейшей практики. Результат зависит от исходного уровня.</p></article></div></section>'
   body=body.replace('<section class="section faq">',course_info+'<section class="section faq">',1)
  body=body.replace('<section class="section faq">',lesson+'<section class="section faq">',1)
  return demo+body
 return home,about,contact,expanded
